/** A dependency cycle a depth-first search found, carrying the names around it in walk order. */
export class CycleError extends Error {
  /**
   * @param {string[]} names - the cycle's names, starting and ending with the re-entered task.
   */
  constructor(names) {
    super(`cycle: ${names.join(' -> ')}`)
    this.name = 'CycleError'
    this.names = names
  }
}

/**
 * Find the first cycle a depth-first search encounters, starting from each task in ascending
 * name order and walking each task's dependencies in ascending name order.
 * @param {Map<string, {needs: string[]}>} tasks - the parsed tasks.
 * @returns {string[] | null} the cycle's names, starting and ending with the re-entered task, or null.
 */
function findCycle(tasks) {
  const state = new Map() // name -> 'visiting' | 'done'
  const stack = []

  function visit(name) {
    state.set(name, 'visiting')
    stack.push(name)
    const needs = [...tasks.get(name).needs].sort()
    for (const need of needs) {
      const status = state.get(need)
      if (status === 'visiting') {
        const start = stack.indexOf(need)
        return [...stack.slice(start), need]
      } else if (status !== 'done') {
        const found = visit(need)
        if (found) return found
      }
    }
    stack.pop()
    state.set(name, 'done')
    return null
  }

  for (const name of [...tasks.keys()].sort()) {
    if (state.get(name) === 'done') continue
    const found = visit(name)
    if (found) return found
  }
  return null
}

/**
 * The tasks in run order: repeatedly the lexicographically smallest task whose
 * dependencies have all been emitted.
 * @param {Map<string, {needs: string[]}>} tasks - the parsed tasks.
 * @returns {string[]} the names in run order.
 * @throws {CycleError} when the graph has a dependency cycle.
 */
export function order(tasks) {
  const cycle = findCycle(tasks)
  if (cycle) throw new CycleError(cycle)

  const remaining = new Set(tasks.keys())
  const emitted = new Set()
  const out = []
  while (remaining.size > 0) {
    const ready = [...remaining].filter(name => tasks.get(name).needs.every(need => emitted.has(need))).sort()
    if (ready.length === 0) break
    remaining.delete(ready[0])
    emitted.add(ready[0])
    out.push(ready[0])
  }
  return out
}
"}

