const DIGEST = /^[0-9a-f]{8}$/

/** One refusal of a snapshot line, carrying the 1-based line it was read from. */
export class SnapshotError extends Error {
  /**
   * @param {number} line - the 1-based line within the snapshot.
   * @param {string} message - the message the specification words, without the `<snapshot>: line N: ` prefix.
   */
  constructor(line, message) {
    super(message)
    this.name = 'SnapshotError'
    this.line = line
  }
}

/**
 * Parse a snapshot's lines into a map of recorded paths to their digests.
 * @param {string[]} lines - the snapshot's own lines.
 * @returns {Map<string, string>} the recorded digest by path.
 * @throws {SnapshotError} on a malformed line.
 */
export function parseSnapshot(lines) {
  const recorded = new Map()
  for (const [index, raw] of lines.entries()) {
    const line = index + 1
    const text = raw.trim()
    if (text === '' || text.startsWith('#')) continue
    const words = text.split(/\s+/u)
    if (words.length !== 2) throw new SnapshotError(line, 'expected <path> <digest>')
    const [path, digest] = words
    if (!DIGEST.test(digest)) throw new SnapshotError(line, `invalid digest ${digest}`)
    if (recorded.has(path)) throw new SnapshotError(line, `path ${path} is recorded twice`)
    recorded.set(path, digest)
  }
  return recorded
}
"}

