function fnv1a(buf) {
  let h = 0x811c9dc5 >>> 0
  for (const b of buf) { h = (h ^ b) >>> 0; h = Math.imul(h, 16777619) >>> 0 }
  return h.toString(16).padStart(8, '0')
}

function randInt(n) { return Math.floor(Math.random() * n) }
function pick(arr) { return arr[randInt(arr.length)] }

let mismatches = 0
const TRIALS = 500

for (let t = 0; t < TRIALS; t++) {
  const dir = mkdtempSync(join(tmpdir(), 'planfuzz-'))
  const filePool = ['f1.txt', 'f2.txt', 'f3.txt', 'f4.txt']
  // create some files randomly in workspace, some not
  const fileContent = {}
  for (const f of filePool) {
    if (Math.random() < 0.7) {
      const content = 'content-' + randInt(5)
      writeFileSync(join(dir, f), content)
