    }
  }

  const n = 2 + randInt(3)
  const names = []
  for (let i = 0; i < n; i++) names.push(String.fromCharCode(97 + i))
  const needsMap = new Map(names.map(x => [x, new Set()]))
  const readsMap = new Map(names.map(x => [x, new Set()]))
  const writesMap = new Map(names.map(x => [x, new Set()]))

  // build a DAG (avoid cycles): only allow a needs b if b < a alphabetically (guarantees acyclic)
  for (const a of names) {
    for (const b of names) {
      if (b < a && Math.random() < 0.4) needsMap.get(a).add(b)
    }
  }
  for (const a of names) {
    for (const f of filePool) {
      if (Math.random() < 0.3) readsMap.get(a).add(f)
      if (Math.random() < 0.3) writesMap.get(a).add(f)
    }
  }

  let taskFile = names.map(nm => `task ${nm} echo ${nm}`).join('\n') + '\n'
  for (const a of names) {
    const deps = [...needsMap.get(a)]
    if (deps.length) taskFile += `needs ${a} ${deps.sort().join(' ')}\n`
    const reads = [...readsMap.get(a)]
    if (reads.length) taskFile += `reads ${a} ${reads.sort().join(' ')}\n`
    const writes = [...writesMap.get(a)]
    if (writes.length) taskFile += `writes ${a} ${writes.sort().join(' ')}\n`
  }

  // build snapshot: for each file in pool, randomly record true digest, wrong digest, or omit
  let snapLines = []
  for (const f of filePool) {
    const roll = Math.random()
    if (roll < 0.15) continue // omit -> new
    if (fileContent[f] !== undefined) {
      const trueDigest = fnv1a(Buffer.from(fileContent[f]))
      if (roll < 0.85) snapLines.push(`${f} ${trueDigest}`)
      else snapLines.push(`${f} ffffffff`) // wrong -> changed (unless collides)
    } else {
      // file missing in workspace but might still get recorded -> "missing"
      snapLines.push(`${f} 01234567`)
    }
  }
  const snapPath = join(dir, 'snap.snap')
  writeFileSync(snapPath, snapLines.join('\n') + '\n')

  // reference computation
  // topo order via same greedy algorithm (DAG guaranteed acyclic)
  function topoOrder() {
    const remaining = new Set(names)
    const emitted = new Set()
    const out = []
    while (remaining.size) {
      const ready = [...remaining].filter(nm => [...needsMap.get(nm)].every(d => emitted.has(d))).sort()
      if (!ready.length) break
      remaining.delete(ready[0]); emitted.add(ready[0]); out.push(ready[0])
    }
    return out
  }
  const recorded = new Map(snapLines.map(l => { const [p, d] = l.split(' '); return [p, d] }))
  const ord = topoOrder()
  const runs = new Map()
  const lines = []
  for (const nm of ord) {
    const watched = [...new Set([...readsMap.get(nm), ...writesMap.get(nm)])].sort()
    let reason = null
    for (const p of watched) {
      if (!recorded.has(p)) { reason = `new ${p}`; break }
      const exists = fileContent[p] !== undefined
      if (!exists) { reason = `missing ${p}`; break }
      const actual = fnv1a(Buffer.from(fileContent[p]))
      if (actual !== recorded.get(p)) { reason = `changed ${p}`; break }
    }
    if (reason === null) {
      const runDeps = [...needsMap.get(nm)].filter(d => runs.get(d)).sort()
      if (runDeps.length) reason = `needs ${runDeps[0]}`
    }
    runs.set(nm, reason !== null)
    lines.push(reason !== null ? `run ${nm} ${reason}` : `skip ${nm}`)
  }
  const r = [...runs.values()].filter(Boolean).length
  const s = runs.size - r
  lines.push(`total run=${r} skip=${s}`)
  const expectedOut = lines.map(l => l + '\n').join('')

  const res = spawnSync(process.execPath, [cli, 'plan', snapPath], { cwd: dir, encoding: 'utf8', input: taskFile })

  if (res.status !== 0 || res.stdout !== expectedOut) {
    mismatches++
    console.log('MISMATCH', { taskFile, snapLines, fileContent, expected: expectedOut, got: res.stdout, err: res.stderr, code: res.status })
    if (mismatches > 5) { rmSync(dir, { recursive: true, force: true }); process.exit(1) }
  }
  rmSync(dir, { recursive: true, force: true })
}
